c.python:
class Solution:
    def trafficSignalColor(self, timer):
        if timer == 0: return "Green"
        if timer == 30: return "Orange"
        if 30 < timer <= 90: return "Red"
        return "Invalid"

c.cpp:
class Solution {
public:
    string trafficSignalColor(int timer) {
        if (timer == 0) return "Green";
        if (timer == 30) return "Orange";
        if (timer > 30 && timer <= 90) return "Red";
        return "Invalid";
    }
};

